WITH benchmark AS (SELECT pct_change AS benchmark FROM `findsl_ext`.`index_quote` WHERE index_code='000300' AND snapshot_id='akshare-sina-index-2026-07-15-42e29790031f' AND bizdate='2026-04-14') SELECT q.mktcode,q.tgtcode,q.bizdate FROM `newzl`.`hsj_stock_hq_basic` q CROSS JOIN benchmark b WHERE q.bizdate='2026-04-14' AND ((q.lastPx-q.preClosePx)*100.0/NULLIF(q.preClosePx,0))>b.benchmark AND ((q.lastPx-q.preClosePx)*100.0/NULLIF(q.preClosePx,0))<1;
